Let me code:

```js
function sweptBrickHit(ball, prevX, prevY, brick) {
  const r = ball.r;
  const bx0 = brick.x - r, by0 = brick.y - r;
  const bx1 = brick.x + brick.w + r, by1 = brick.y + brick.h + r;
  const ox = prevX, oy = prevY;
  const dx = ball.x - prevX, dy = ball.y - prevY;

  let tmin = 0, tmax = 1;
  let hitAxis = null;

  // X slab
  if (dx === 0) {
    if (ox < bx0 || ox > bx1) return null;
  } else {
    let t1 = (bx0 - ox) / dx;
    let t2 = (bx1 - ox) / dx;
    const axis = dx >= 0 ? 'vx' : 'vx'; // which face
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > tmin) { tmin = t1; hitAxis = 'x'; }
    tmax = Math.min(tmax, t2);
    if (tmin > tmax) return null;
  }

  // Y slab
  if (dy === 0) {
    if (oy < by0 || oy > by1) return null;
  } else {
    let t1 = (by0 - oy) / dy;
    let t2 = (by1 - oy) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > tmin) { tmin = t1; hitAxis = 'y'; }
    tmax = Math.min(tmax, t2);
    if (tmin > tmax) return null;
  }

  if (tmin > 1) return null; // hit after this step
  return { t: Math.max(0, tmin), axis: hitAxis };
}
```

