// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Returns the live bricks the ball is currently overlapping (the brick hit
// primitive). Pure & testable; the bounce resolution builds on top of it.
export function brickHit(ball, bricks) {
  const hits = [];
  for (const brick of bricks) {
    if (brick.alive && collides(ball, brick)) hits.push(brick);
  }
  return hits;
}

// Swept AABB test between the ball's previous and current positions, against a
// single (already inflated by the ball radius) brick box. Returns the first
// time `t` in [0, 1] along the segment at which the ball edge touches the
// brick, or null if the path never crosses it.
//
// This closes the tunnelling gap (#1): at high speeds a single discrete sample
// can jump clean over a brick (`ballSpeed(6) * 0.05s` = 35.5 px vs ~34 px to
// cross), so we check the whole segment instead of just the end point.
function sweptEntry(ball, prevX, prevY, brick) {
  const loX = brick.x - ball.r;
  const hiX = brick.x + brick.w + ball.r;
  const loY = brick.y - ball.r;
  const hiY = brick.y + brick.h + ball.r;

  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let tEnter = 0;
  let tExit = 1;

  if (dx === 0) {
    if (prevX < loX || prevX > hiX) return null;
  } else {
    let a = (loX - prevX) / dx;
    let b = (hiX - prevX) / dx;
    if (a > b) [a, b] = [b, a];
    tEnter = Math.max(tEnter, a);
    tExit = Math.min(tExit, b);
    if (tEnter > tExit) return null;
  }

  if (dy === 0) {
    if (prevY < loY || prevY > hiY) return null;
  } else {
    let a = (loY - prevY) / dy;
    let b = (hiY - prevY) / dy;
    if (a > b) [a, b] = [b, a];
    tEnter = Math.max(tEnter, a);
    tExit = Math.min(tExit, b);
    if (tEnter > tExit) return null;
  }

  return { t: Math.max(0, tEnter) };
}

// Deflects the ball off the brick it hit, exactly once, and leaves it resting
// on the contact face so it cannot re-collide on the next frame (no sticky
// bounce). The face is chosen by the smaller penetration axis; equal
// penetrations mean a diagonal (corner) hit and flip both components.
// `entry` is the point where the ball first touched the brick.
function bounceBall(ball, brick, entry) {
  const r = ball.r;

  const penTop = entry.y + r - brick.y;
  const penBottom = brick.y + brick.h - (entry.y - r);
  const penLeft = entry.x + r - brick.x;
  const penRight = brick.x + brick.w - (entry.x - r);

  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);

  const diagonal = Math.abs(penX - penY) <= 1e-9;
  if (diagonal) {
    // Corner hit: reconcile both components.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = penLeft < penRight ? brick.x - r : brick.x + brick.w + r;
    ball.y = penTop < penBottom ? brick.y - r : brick.y + brick.h + r;
  } else if (penY < penX) {
    // Top / bottom face.
    ball.vy = -ball.vy;
    ball.x = entry.x;
    ball.y = penTop < penBottom ? brick.y - r : brick.y + brick.h + r;
  } else {
    // Left / right face.
    ball.vx = -ball.vx;
    ball.x = penLeft < penRight ? brick.x - r : brick.x + brick.w + r;
    ball.y = entry.y;
  }
}

// Breaks every brick the ball's path touches this step, credits the score, and
// applies a single bounce. Returns true if any brick was hit.
// `prevX`/`prevY` are the ball position before `step()` moved it.
export function resolveBricks(state, prevX, prevY) {
  const ball = state.ball;
  const hits = [];

  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const entry = sweptEntry(ball, prevX, prevY, brick);
    if (entry) hits.push({ brick, entry });
  }
  if (hits.length === 0) return false;

  // Bounce is decided by the first brick the ball touches along its path, so a
  // seam (8 px gap vs 14 px ball) that overlaps two bricks in one pass still
  // yields exactly one deflection instead of two that cancel out.
  hits.sort((a, b) => a.entry.t - b.entry.t);
  const { brick: firstBrick, entry } = hits[0];

  for (const { brick } of hits) {
    if (!brick.alive) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  const t = entry.t;
  bounceBall(ball, firstBrick, {
    x: prevX + t * (ball.x - prevX),
    y: prevY + t * (ball.y - prevY),
  });
  return true;
}

